import{_ as l,l as n,o as e,c as r,v as t,p as s,x as i,d as p,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"逆向选择对非执行风险","description":"","frontmatter":{"title":"逆向选择对非执行风险","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/adverse-selection-vs-nonexecution.md","filePath":"quant/adverse-selection-vs-nonexecution.md","lastUpdated":1789023840000}'),c={name:"quant/adverse-selection-vs-nonexecution.md"};function h(u,a,_,f,E,x){const o=n("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="逆向选择对非执行风险" tabindex="-1">逆向选择对非执行风险 <a class="header-anchor" href="#逆向选择对非执行风险" aria-label="Permalink to &quot;逆向选择对非执行风险&quot;">​</a></h1><div class="epigraph"><p>限价单有两种死法：成交在对你不利的时候（被捡），或到截止仍不成交（非执行）。最优挂单是在这两份风险之间分配，而不是单独最小化其中一份。</p><footer>—— 据 Foucault 对 picking-off 与等待的讨论；对照 Copeland and Galai, Information Effects on the Bid-Ask Spread, Journal of Finance, 1983</footer></div><p><a href="/quant/limit-vs-market-choice">限价对市价</a>给出何时离开队列去吃。缺口是：一旦选择限价，失败有两种经济学完全相反的方式。逆向选择（成交条件于坏消息）要求你挂得更保守、或更勤撤单；非执行（\\(\\pi_{\\mathrm{fill}}\\) 太低）要求你挂得更有攻击性。两者对价格的含义相反。本课把权衡写清，为下一课最优放置提供目标函数，不重推 Foucault 均衡存在。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>被捡是条件于成交的损失：\\(E[V\\mid\\)成交\\(]\\) 比挂单价更差。非执行是条件于不成交的损失：你仍要在更差的价格完成，或根本完不成对冲。只防被捡，会把单子埋到远处，几乎永不成交，截止时被迫吃更宽的价差——非执行成本爆掉。只防非执行，会贴在 BBO 甚至越过，变成几乎市价，再加被捡。问题是同一决策变量（挂单价、展示、撤单频率）如何同时进入两份期望损失。</p><p>Easley–O&#39;Hara 的事件不确定放大被捡：有事件时成交更可能到来。Parlour 的队深放大非执行：队尾 \\(\\pi_{\\mathrm{fill}}\\) 低。状态要把两者同时包括。</p><h3 id="成交是坏消息-不成交也是消息" tabindex="-1">成交是坏消息，不成交也是消息 <a class="header-anchor" href="#成交是坏消息-不成交也是消息" aria-label="Permalink to &quot;成交是坏消息，不成交也是消息&quot;">​</a></h3><p>限价卖出成交，暗示有人愿意在此刻买，可能是好消息（对卖方不利）。限价卖出一直不成交，可能是没有买家，也可能价值正在下跌、市价单去打买方。不成交更新事件后验，与「无交易是无事件」同族。把非执行当成外生概率噪声，会丢掉学习。</p><p><span class="marginnote">执行算法文献把非执行叫做 implementation risk，把被捡叫做 adverse selection 或 toxicity。本课保持微观结构用语，不引入新的经纪商标签。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>限价卖在价格 \\(p\\) 的期望效用可写成</p> \\[\\pi(p)\\,E[p-V\\mid \\text{fill at }p] + (1-\\pi(p))\\,U_{\\mathrm{nx}}(p), \\]<p>其中 \\(\\pi\\) 随 \\(p\\) 更有攻击性而升（非执行降），条件期望 \\(E[V\\mid\\mathrm{fill}]\\) 同时变差（逆向选择升）。一阶条件：放松 \\(p\\) 带来的成交概率收益，等于边际被捡恶化。波动 \\(\\sigma\\) 主要进入条件期望；队深 \\(n\\) 主要进入 \\(\\pi\\)；截止 \\(T\\) 进入 \\(U_{\\mathrm{nx}}\\)。</p><p>经验分离：成交后中点向对手方向永久移动，是被捡/信息；限价撤单后自己改市价且中点未走，是非执行。Hasbrouck 永久影响对「限价成交」子样本应高于「随机时刻」，若限价成交被选中为信息事件。</p><h3 id="两种风险的日内节奏" tabindex="-1">两种风险的日内节奏 <a class="header-anchor" href="#两种风险的日内节奏" aria-label="Permalink to &quot;两种风险的日内节奏&quot;">​</a></h3><p>开盘事件不确定高，被捡权重大，挂单应更保守或更短寿命。收盘截止硬，非执行权重大，同一人改贴 BBO 或改市价。这与策略噪声的收盘聚集一致，不必假设下午知情者变多。公告窗口两者同时升：\\(\\pi\\) 可能升（活动密）但 \\(E[V\\mid\\mathrm{fill}]\\) 更毒，净效应是价差宽、限价寿命短。</p>',16)),(e(),s(m,null,{default:i(()=>[d(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22%E6%8C%82%E5%8D%95%E4%BB%B7%20p%22%5D%20--%3E%20Pi%5B%22%CF%80fill%20%E9%9D%9E%E6%89%A7%E8%A1%8C%22%5D%0A%20%20P%20--%3E%20AS%5B%22E%5BV%7Cfill%5D%20%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%22%5D%0A%20%20Pi%20--%3E%20Obj%5B%22%E6%9C%9F%E6%9C%9B%E6%95%88%E7%94%A8%22%5D%0A%20%20AS%20--%3E%20Obj%0A%20%20Nx%5B%22%E6%88%AA%E6%AD%A2%E6%97%B6%20U_nx%22%5D%20--%3E%20Obj%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>流动性供给的「公平价差」必须同时买这两份保险。只按 Glosten-Milgrom 补偿逆向选择，会低估那些必须成交的挂单者所要求的攻击性溢价；只按库存补偿等待，会低估被捡。HFT 做市把撤单速度当作第三工具：降低限价寿命，同时压被捡与（若补得够快）非执行。速度竞赛单元会说明第三工具的社会成本。</p><p>对效率：被捡主导时，成交更有信息，VR 的短正自相关来自信息写入；非执行主导时，更多是队列摩擦，价格暂时成分来自补给。度量时要把限价成交与市价成交分开算永久影响。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>公式是部分均衡：\\(\\pi(p)\\) 依赖别人的策略。结构估计要回到 Goettler–Parlour–Rajan 一类计算均衡。隐藏单分别改变可见 \\(\\pi\\) 与真实被捡，下一课之后再拆。多市场时本地不成交不等于全局非执行，智能路由改写 \\(U_{\\mathrm{nx}}\\)。</p><p><span class="marginnote">实现价差为负，常常是被捡项赢了；限价完成率低，常常是非执行项赢了。两个 KPI 一起看，才知道阈值往哪边偏。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>限价失败有被捡与非执行两种；对挂单价的比较静态相反。</li><li>最优是边际成交概率收益等于边际逆向选择恶化，再加截止惩罚。</li><li>开盘偏防被捡，收盘偏防非执行；公告窗口两者同时恶化。</li><li>出处：Copeland and Galai, <em>Journal of Finance</em>, 1983；Foucault, <em>Journal of Financial Markets</em>, 1999；动态权衡见 Roşu, 2009。</li></ul>',8))])}const q=l(c,[["render",h]]);export{b as __pageData,q as default};
